import json
import argparse
import os
from pathlib import Path
import shutil
import socket
import sqlite3
import subprocess
import sys
import time
from urllib.request import urlopen
from datetime import datetime

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))
from evaluate_original import SCENARIOS, prepare, run


def free_port():
    with socket.socket() as sock:
        sock.bind(('127.0.0.1', 0))
        return sock.getsockname()[1]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--browser-executable', type=Path, help='Explicit installed Chromium; records browser variance, skips download')
    args = parser.parse_args()
    if args.browser_executable and not args.browser_executable.is_file():
        parser.error('browser executable must exist')
    app = ROOT / 'output/demo'
    output = ROOT / 'output/481demo-quality-analysis' / datetime.now().strftime('acceptance-%Y%m%d-%H%M%S-%f')
    backend_port, frontend_port = free_port(), free_port()
    while frontend_port == backend_port:
        frontend_port = free_port()
    prepare(output, f'http://127.0.0.1:{frontend_port}')
    if args.browser_executable:
        config = output / 'playwright.config.cjs'
        config.write_text(config.read_text(encoding='utf-8').replace(
            'module.exports = ', 'const config = ', 1) + '\nconfig.use.launchOptions = ' + json.dumps(
                {'executablePath': str(args.browser_executable.resolve())}) + ';\nmodule.exports = config;\n', encoding='utf-8')
    report = {'kind': 'historical_application_reuse_diagnostic', 'output': str(output),
              'steps': [], 'accepted': False, 'error': None, 'cleanup': [],
              'raw_scenarios': {scenario: [] for scenario in SCENARIOS},
              'browser_executable': str(args.browser_executable) if args.browser_executable else None}
    processes, logs = [], []
    started = time.perf_counter()

    def command(name, argv, cwd=output):
        begin = time.perf_counter()
        step = {'name': name, 'exit_code': None}
        try:
            with (output / f'{name}.log').open('w', encoding='utf-8') as log:
                process = subprocess.Popen(argv, cwd=cwd, env=env, stdout=log, stderr=log,
                                           creationflags=subprocess.CREATE_NO_WINDOW)
                try:
                    code = process.wait(timeout=600)
                except subprocess.TimeoutExpired:
                    subprocess.run(['taskkill', '/PID', str(process.pid), '/T', '/F'], capture_output=True)
                    process.wait(timeout=15)
                    raise
            step['exit_code'] = code
        except Exception as error:
            step['error'] = f'{type(error).__name__}: {error}'
            raise
        finally:
            step['elapsed_seconds'] = time.perf_counter() - begin
            report['steps'].append(step)
        if code:
            raise RuntimeError(f'{name} exited {code}')

    env = os.environ.copy()
    env.pop('NODE_PATH', None)
    env['npm_config_cache'] = str(ROOT / 'output/npm-cache')
    try:
        command('install-runner', [shutil.which('npm.cmd'), 'install', '--include=dev', '--no-audit', '--no-fund'])
        if not args.browser_executable:
            command('install-browser', ['node', 'node_modules/playwright/cli.js', 'install', 'chromium'])
        services = [
            ('backend', ['node', str(app / 'node_modules/tsx/dist/cli.mjs'), str(app / 'backend/src/server.ts')], app,
             {'DATABASE_URL': str(output / 'app.db'), 'PORT': str(backend_port)}, f'http://127.0.0.1:{backend_port}/api/health'),
            ('frontend', ['node', str(app / 'node_modules/vite/bin/vite.js'), '--config', str(app / 'frontend/vite.e2e.config.ts'),
                          '--host', '127.0.0.1', '--port', str(frontend_port), '--strictPort'], app / 'frontend',
             {'ARC_BACKEND_URL': f'http://127.0.0.1:{backend_port}'}, f'http://127.0.0.1:{frontend_port}/'),
        ]
        for name, argv, cwd, extra, url in services:
            begin = time.perf_counter()
            step = {'name': f'start-{name}', 'ready': False}
            report['steps'].append(step)
            log = (output / f'{name}.log').open('w', encoding='utf-8')
            logs.append(log)
            process = subprocess.Popen(argv, cwd=cwd, env={**env, **extra}, stdout=log, stderr=log,
                                       creationflags=subprocess.CREATE_NO_WINDOW)
            processes.append((name, process))
            step['pid'] = process.pid
            deadline = time.monotonic() + 30
            while True:
                if process.poll() is not None:
                    raise RuntimeError(f'{name} exited {process.returncode}')
                try:
                    with urlopen(url, timeout=1) as response:
                        if response.status == 200:
                            break
                except OSError:
                    pass
                if time.monotonic() >= deadline:
                    raise RuntimeError(f'{name} readiness timeout')
                time.sleep(0.2)
            step.update(ready=True, elapsed_seconds=time.perf_counter() - begin)
        with urlopen(f'http://127.0.0.1:{frontend_port}/api/session', timeout=5) as response:
            if response.status != 200 or json.load(response) != {'authenticated': False}:
                raise RuntimeError('session proxy unavailable')
        for name in ('helpers.ts', 'REQ-1.spec.ts', 'REQ-2.spec.ts'):
            if (output / 'tests' / name).read_bytes() != (ROOT / 'input/tests' / name).read_bytes():
                raise RuntimeError('original test bytes changed')
        # run() inherits the parent environment; explicitly suppress external module resolution.
        old_node_path = os.environ.pop('NODE_PATH', None)
        try:
            code = run(output, ['node', str(app / 'node_modules/tsx/dist/cli.mjs'),
                                str(Path(__file__).with_name('reset-seed.mts')), str(app), str(output / 'app.db')])
        finally:
            if old_node_path is not None:
                os.environ['NODE_PATH'] = old_node_path
        report['acceptance'] = json.loads((output / 'summary.json').read_text(encoding='utf-8'))
        results = output / 'results.json'
        if results.exists():
            def visit(suite):
                for spec in suite.get('specs', []):
                    scenario = spec['title'].split(':', 1)[0]
                    if scenario in report['raw_scenarios']:
                        report['raw_scenarios'][scenario].extend(
                            {'status': result.get('status'), 'retry': result.get('retry'),
                             'duration_ms': result.get('duration')}
                            for test in spec.get('tests', []) for result in test.get('results', []))
                for child in suite.get('suites', []):
                    visit(child)
            visit(json.loads(results.read_text(encoding='utf-8')))
        report['accepted'] = code == 0
    except Exception as error:
        report['error'] = f'{type(error).__name__}: {error}'
    finally:
        for name, process in reversed(processes):
            cleanup = {'name': name}
            try:
                cleanup['taskkill_exit_code'] = subprocess.run(
                    ['taskkill', '/PID', str(process.pid), '/T', '/F'], capture_output=True).returncode
                process.wait(timeout=15)
                cleanup['process_exit_code'] = process.returncode
            except Exception as error:
                cleanup['error'] = f'{type(error).__name__}: {error}'
            report['cleanup'].append(cleanup)
        for log in logs:
            log.close()
        report['ports_released'] = True
        for port in (backend_port, frontend_port):
            with socket.socket() as sock:
                try:
                    sock.bind(('127.0.0.1', port))
                except OSError:
                    report['ports_released'] = False
        if (output / 'app.db').exists():
            with sqlite3.connect(output / 'app.db') as db:
                report['database_counts'] = {table: db.execute(f'SELECT COUNT(*) FROM {table}').fetchone()[0]
                                             for table in ('Account', 'Session')}
        report['elapsed_seconds'] = time.perf_counter() - started
        (output / 'orchestration.json').write_text(json.dumps(report, indent=2), encoding='utf-8')
    print(json.dumps(report, indent=2))
    return 0 if report['accepted'] and report['ports_released'] and all(
        'error' not in item and item.get('taskkill_exit_code') == 0 for item in report['cleanup']) else 1


if __name__ == '__main__':
    raise SystemExit(main())
