from infrastructure.utils.processes import capture_process, npm_command


def check_npm_cache(output_dir: Path) -> None:
    """Probe cache writes and the host user lookup required by the tsx test runner."""
    output_dir.mkdir(parents=True, exist_ok=True)
    result = capture_process([*npm_command(), "config", "get", "cache"],
        cwd=output_dir, timeout=30)
    if result["returncode"]:
        raise ValueError("npm cache preflight could not resolve cache configuration")
    value = result["stdout"].strip()
    if not value:
        raise ValueError("npm cache preflight returned an empty cache path")
    cache = Path(value)
    if not cache.is_absolute():
        cache = output_dir / cache
    try:
        cache.mkdir(parents=True, exist_ok=True)
        with NamedTemporaryFile(prefix="arc-preflight-", dir=cache) as probe:
            probe.write(b"cache write probe\n")
            probe.flush()
    except OSError as error:
        raise ValueError("npm cache is not writable; set npm_config_cache to a writable "
            "directory and retry before model compilation") from error
    # tsx needs this host capability just to start the fixed backend test runner.
    # Probe Node itself: npm config can succeed while os.userInfo() fails.
    result = capture_process([shutil.which("node"), "-e", "require('node:os').userInfo()"],
        cwd=output_dir, timeout=30)
    if result["returncode"]:
        raise ValueError("Node os.userInfo() is unavailable; the required tsx backend "
